"""Generate typed codecs only for structurally symmetric, straight-line source packets.
Complex packets deliberately require handwritten ports. Not used at runtime/build time.
"""
import ast, pathlib, re, textwrap
ROOT=pathlib.Path(__file__).resolve().parents[2]
s=(ROOT/'shared/packet.pyx').read_text()
base=ROOT/'java/src/main/java/net/battlespades/protocol'
specs=[]
read_types={'read_byte':('int','u8'),'read_short':('int','i16'),'read_int':('int','i32'),'read_uint64':('long','u64'),'read_float':('float','f32'),'read_string':('String','string')}
write_types={'write_byte':'u8','write_short':'i16','write_int':'i32','write_uint64':'u64','write_float':'f32','write_string':'string'}
for match in re.finditer(r'^cdef class (\w+)\(Loader\):(.*?)(?=^cdef class |\Z)',s,re.M|re.S):
    name,body=match.groups()
    ident=re.search(r'id: int = (-?\d+)',body)
    if not ident or int(ident[1])<0: continue
    rd=re.search(r'    cpdef read\(self, ByteReader reader\):(.*?)(?=\n    (?:cpdef|def) |\Z)',body,re.S)
    wr=re.search(r'    cpdef write\(self, ByteWriter writer\):(.*?)(?=\n    (?:cpdef|def) |\Z)',body,re.S)
    if not rd or not wr: continue
    fields=[]; reads=[]; writes=[]
    try:
        rt=ast.parse(textwrap.dedent(rd[1])); wt=ast.parse(textwrap.dedent(wr[1]))
        for n in rt.body:
            if isinstance(n, ast.Pass): continue
            if not isinstance(n,ast.Assign) or len(n.targets)!=1: raise ValueError()
            target=n.targets[0]
            if not isinstance(target,ast.Attribute) or not isinstance(target.value,ast.Name) or target.value.id!='self': raise ValueError()
            field=target.attr
            if field in {'type','yield','default','class','switch','new'}: field+='Value'
            value=n.value
            if isinstance(value,ast.Call) and isinstance(value.func,ast.Attribute) and isinstance(value.func.value,ast.Name) and value.func.value.id=='reader' and value.func.attr in read_types and not value.args:
                typ,method=read_types[value.func.attr]; expr='r.'+method+'()'
            elif isinstance(value,ast.Call) and isinstance(value.func,ast.Name) and value.func.id=='read_color': typ,expr='int','r.color()'
            else: raise ValueError()
            fields.append((target.attr,field,typ)); reads.append(expr)
        consumed=[]
        for ix,n in enumerate(wt.body):
            if not isinstance(n,ast.Expr) or not isinstance(n.value,ast.Call): raise ValueError()
            c=n.value
            if isinstance(c.func,ast.Attribute) and isinstance(c.func.value,ast.Name) and c.func.value.id=='writer' and c.func.attr in write_types and len(c.args)==1:
                arg=c.args[0]
                if ix==0 and ast.unparse(arg)=='self.id' and c.func.attr=='write_byte': continue
                if not isinstance(arg,ast.Attribute) or not isinstance(arg.value,ast.Name) or arg.value.id!='self': raise ValueError()
                source=arg.attr; method=write_types[c.func.attr]
            elif isinstance(c.func,ast.Name) and c.func.id=='write_color' and len(c.args)==2 and ast.unparse(c.args[0])=='writer' and isinstance(c.args[1],ast.Attribute): source=c.args[1].attr; method='color'
            else: raise ValueError()
            found=[f for f in fields if f[0]==source]
            if not found: raise ValueError()
            consumed.append(source); writes.append('w.'+method+'('+found[0][1]+');')
        if consumed != [f[0] for f in fields]: raise ValueError()
    except (SyntaxError,ValueError): continue
    specs.append(dict(name=name,id=int(ident[1]),fields=fields,reads=reads,writes=writes))
header='// SPDX-License-Identifier: AGPL-3.0-or-later\n// Generated by tools/generate_simple_packets.py from shared/packet.pyx.\npackage net.battlespades.protocol;\n\n'
text=header+'/** Source-derived straight-line packet codecs. Complex packets are separate. */\npublic final class SimplePackets {\n    private SimplePackets() {}\n'
for spec in specs:
    params=', '.join(t+' '+j for _,j,t in spec['fields'])
    text+=f"    public record {spec['name']}({params}) implements GamePacket {{\n        @Override public int id() {{ return {spec['id']}; }}\n        @Override public void write(Wire.Writer w) {{ w.u8(id()); {' '.join(spec['writes'])} }}\n    }}\n"
text+='}\n'; (base/'SimplePackets.java').write_text(text)
switch=header+'import static net.battlespades.protocol.SimplePackets.*;\n\npublic final class PacketCodec {\n    private PacketCodec() {}\n    public static GamePacket decode(byte[] data) {\n        var r = new Wire.Reader(data);\n        int id = r.u8();\n        GamePacket packet = switch(id) {\n'
for spec in sorted(specs,key=lambda x:x['id']): switch+=f"            case {spec['id']} -> new {spec['name']}({', '.join(spec['reads'])});\n"
switch+='            case 17 -> MatchPackets.ChangePlayer.read(r);\n            case 50 -> MatchPackets.LocalisedMessage.read(r);\n            case 5 -> LifePackets.SetHP.read(r);\n            case 6 -> ShootPacket.read(r);\n            case 9 -> CombatPackets.ShootResponse.read(r);\n            case 20 -> CombatPackets.HitEntity.read(r);\n            case 23 -> AudioPackets.PlaySound.read(r);\n            case 16 -> ChangeEntity.read(r);\n            case 67 -> ScorePackets.GameStats.read(r);\n            case 73 -> ScorePackets.ShowTextMessage.read(r);\n            case 71 -> DropPickup.read(r);\n            case 46 -> LifePackets.KillAction.read(r);\n            case 76 -> LifePackets.WeaponReload.read(r);\n            case 2 -> WorldUpdate.read(r);\n            case 4 -> ClientInput.read(r);\n            case 13 -> PlayerPackets.SetClassLoadout.read(r);\n            case 14 -> PlayerPackets.ExistingPlayer.read(r);\n            case 28 -> PlayerPackets.CreatePlayer.read(r);\n            case 38 -> BlockManagerState.read(r);\n            case 21 -> new CreateEntity(EntityRecord.read(r));\n            case 37 -> DamagePacket.read(r);\n            case 45 -> StateData.read(r);\n            case 55 -> new LoadingPackets.MapSyncStart();\n            case 56,57 -> LoadingPackets.MapChunk.read(id,r);\n            case 105 -> LoadingPackets.SteamSessionTicket.read(r);\n            case 114 -> InitialInfo.read(r);\n            default -> throw new ProtocolException("Unsupported packet ID: " + id);\n        };\n        r.end();\n        return packet;\n    }\n}\n'
manual_ids=[17,50,67,73,71,16,23,9,20,6,5,46,76,2,4,13,14,21,28,37,38,45,55,56,57,105,114]
ids=sorted({p['id'] for p in specs}|set(manual_ids))
support='    public static boolean supports(int id) { return switch(id) { case '+','.join(map(str,ids))+' -> true; default -> false; }; }\n'
switch=switch[:-2]+support+'}\n'
(base/'PacketCodec.java').write_text(switch)
(ROOT/'java/docs/simple-packets.json').write_text(__import__('json').dumps(specs,indent=2)+'\n')
print(len(specs),'typed packet codecs:', ', '.join(p['name'] for p in specs))
